"""Legacy commercial operator console HTML retained for compatibility.

This is static UI content only. Production app_v924 receives it through
changying.compat.legacy so the existing /operator-console route can render
without importing the older app_v923 module or executing its side effects.
"""

OPERATOR_HTML = '<!doctype html>\n<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#5362e8">\n<title>长缨辅学｜商业运营控制台</title>\n<style>\n:root{--p:#5362e8;--bg:#f4f6fb;--card:#fff;--line:#e5e8f0;--text:#1f2738;--muted:#778095;--green:#27835c;--red:#bb3145;--amber:#9a6a17}\n*{box-sizing:border-box}body{margin:0;background:var(--bg);font-family:-apple-system,BlinkMacSystemFont,"PingFang SC","Microsoft YaHei",sans-serif;color:var(--text)}\nmain{max-width:1180px;margin:auto;padding:calc(22px + env(safe-area-inset-top)) 16px calc(70px + env(safe-area-inset-bottom))}.top{display:flex;gap:12px;justify-content:space-between;align-items:center;flex-wrap:wrap;margin-bottom:16px}.top h1{font-size:25px;margin:0}.top p{margin:5px 0 0;color:var(--muted)}\n.card{background:var(--card);border:1px solid var(--line);border-radius:18px;padding:16px;box-shadow:0 4px 18px rgba(31,39,56,.04)}.grid{display:grid;gap:12px}.kpis{grid-template-columns:repeat(4,minmax(0,1fr));margin-bottom:14px}.kpi b{font-size:25px;color:var(--p)}.kpi small{display:block;color:var(--muted);margin-top:5px}\n.actions{display:flex;gap:8px;flex-wrap:wrap}.btn{border:0;border-radius:11px;padding:10px 13px;font-weight:700;background:#eef0ff;color:#4350d5;cursor:pointer}.btn.primary{background:var(--p);color:#fff}.btn.danger{background:#ffecef;color:var(--red)}.btn.green{background:#eaf8f2;color:var(--green)}\ninput,select,textarea{width:100%;border:1px solid #dfe3ee;border-radius:11px;padding:11px;font:inherit;background:white}textarea{min-height:76px;resize:vertical}label{display:grid;gap:5px;font-size:13px;color:var(--muted)}.formgrid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:11px}.wide{grid-column:1/-1}\n.badge{display:inline-flex;align-items:center;border-radius:999px;padding:5px 9px;font-size:12px;font-weight:800;background:#eef0ff;color:#4350d5}.badge.green{background:#eaf8f2;color:var(--green)}.badge.red{background:#ffecef;color:var(--red)}.badge.amber{background:#fff5df;color:var(--amber)}\n.toolbar{display:flex;gap:9px;flex-wrap:wrap;margin:14px 0}.toolbar input{max-width:320px}.toolbar select{width:auto;min-width:145px}.school{margin-bottom:12px}.school-head{display:flex;justify-content:space-between;gap:12px;align-items:flex-start;flex-wrap:wrap}.school h3{margin:0 0 5px;font-size:19px}.muted{color:var(--muted)}.usage{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;margin:12px 0}.usage div{background:#f8f9fc;border-radius:12px;padding:10px}.usage b{display:block;font-size:17px}.usage small{color:var(--muted)}\n.quick{display:flex;gap:7px;flex-wrap:wrap;border-top:1px solid var(--line);padding-top:12px;margin-top:12px}.quick .btn{font-size:12px;padding:8px 10px}#gate{max-width:520px;margin:14vh auto}.note{padding:11px 12px;border-radius:12px;background:#fff7e7;color:#7b5719;font-size:13px;line-height:1.6}.secret{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;background:#f7f8fb;border-radius:10px;padding:10px;overflow-wrap:anywhere}\n.overlay{position:fixed;inset:0;background:rgba(20,27,45,.42);display:none;align-items:flex-end;justify-content:center;z-index:99}.overlay.show{display:flex}.modal{background:#fff;width:min(760px,100%);max-height:88dvh;overflow:auto;border-radius:22px 22px 0 0;padding:18px 16px calc(24px + env(safe-area-inset-bottom))}.event{border-bottom:1px solid var(--line);padding:10px 0}.event:last-child{border:0}.json{font:12px ui-monospace,SFMono-Regular,Menlo,monospace;white-space:pre-wrap;background:#f7f8fb;border-radius:10px;padding:9px;margin-top:6px;overflow-wrap:anywhere}.quota-grid{display:grid;grid-template-columns:110px 1fr 1fr;gap:8px;align-items:end}.quota-grid b{padding-bottom:11px}\n@media(max-width:720px){.kpis{grid-template-columns:repeat(2,minmax(0,1fr))}.formgrid{grid-template-columns:1fr}.usage{grid-template-columns:repeat(3,1fr)}.top h1{font-size:22px}.quota-grid{grid-template-columns:1fr}.quota-grid b{padding:4px 0 0}}\n</style></head>\n<body><main>\n<section id="gate" class="card"><h1 style="margin-top:0">商业运营控制台</h1><p class="muted">仅运营方使用。密钥只保存在当前浏览器会话中。</p><label>COMMERCIAL_ADMIN_KEY<input id="key" type="password" autocomplete="off" placeholder="输入 Render 中配置的商业运营密钥"></label><div class="actions" style="margin-top:12px"><button class="btn primary" onclick="connect()">进入控制台</button></div><p class="note">请勿把运营密钥发给学校管理员或客户，也不要在截图中显示。</p></section>\n<section id="app" style="display:none"><div class="top"><div><h1>长缨辅学 · 商业运营控制台</h1><p>V9.2.3 商业版 C2.3 · 学校状态 / 套餐 / 额度 / 到期日 / 操作留痕</p></div><div class="actions"><button class="btn primary" onclick="openCreate()">＋新建试用客户</button><button class="btn" onclick="showOperations()">操作记录</button><button class="btn" onclick="reload()">刷新</button><button class="btn danger" onclick="logout()">退出</button></div></div><div id="kpis" class="grid kpis"></div><div class="toolbar"><input id="search" placeholder="搜索学校、代码、联系人、管理员账号" oninput="renderSchools()"><select id="statusFilter" onchange="renderSchools()"><option value="">全部状态</option><option value="active">已开通</option><option value="trial">试用中</option><option value="grace">宽限期</option><option value="expired">已到期</option><option value="paused">已暂停</option><option value="followup">待跟进</option></select><select id="planFilter" onchange="renderSchools()"><option value="">全部套餐</option></select></div><div id="schools"></div></section>\n</main><div id="overlay" class="overlay" onclick="if(event.target===this)closeModal()"><div id="modal" class="modal"></div></div>\n<script>\nlet KEY=sessionStorage.getItem("commercialKey")||"",schools=[],plans=[],CREATED_CREDENTIAL="";\nconst $=s=>document.querySelector(s),esc=s=>String(s??"").replace(/[&<>"\']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","\\"":"&quot;","\'":"&#39;"}[c]));\nfunction headers(){return {"Content-Type":"application/json","X-Commercial-Key":KEY}}\nasync function op(path,opt={}){const r=await fetch(path,{...opt,headers:{...headers(),...(opt.headers||{})}});let d=null;try{d=await r.json()}catch{}if(!r.ok)throw new Error(d?.detail||`请求失败 ${r.status}`);return d}\nfunction toast(msg){alert(msg)} function statusClass(s){return s==="active"?"green":(s==="expired"||s==="paused")?"red":"amber"} function planName(code){return plans.find(x=>x.code===code)?.name||code}\nfunction dateOnly(v){return v?(v.includes("T")?v.slice(0,16).replace("T"," "):v):""} function dateInput(v){return v?v.slice(0,10):""}\nasync function connect(){KEY=$("#key").value.trim();if(!KEY)return toast("请输入运营密钥");sessionStorage.setItem("commercialKey",KEY);try{await reload();$("#gate").style.display="none";$("#app").style.display=""}catch(e){sessionStorage.removeItem("commercialKey");KEY="";toast(e.message)}}\nfunction logout(){sessionStorage.removeItem("commercialKey");location.reload()}\nasync function reload(){const [summary,rows,p]=await Promise.all([op("/operator/summary"),op("/operator/schools"),fetch("/commercial/plans").then(r=>r.json())]);schools=rows;plans=p.plans||[];const pf=$("#planFilter"),old=pf.value;pf.innerHTML=`<option value="">全部套餐</option>`+plans.map(x=>`<option value="${esc(x.code)}">${esc(x.name)}</option>`).join("");pf.value=old;renderSummary(summary);renderSchools()}\nfunction renderSummary(s){$("#kpis").innerHTML=[["客户学校",s.totalSchools],["试用中",s.trial],["已开通",s.active],["已暂停",s.paused],["7天内试用到期",s.trialEnding7d],["宽限期",s.grace],["已到期",s.expired],["待跟进",s.followupDue],["在用教师",s.activeTeachers],["在读学生",s.activeStudents],["待完善联系人",s.missingContact]].map(x=>`<div class="card kpi"><b>${x[1]??0}</b><small>${x[0]}</small></div>`).join("")}\nfunction planLimit(v){return v===null||v===undefined?"不限":v}\nfunction expiryText(s){if(s.status==="trial")return s.trialEndsAt?`试用至 ${dateOnly(s.trialEndsAt)}`:"试用中";if(s.status==="active")return s.periodEndsAt?`服务到期 ${dateOnly(s.periodEndsAt)}`:"长期有效";if(s.status==="grace")return s.graceEndsAt?`宽限至 ${dateOnly(s.graceEndsAt)}`:"宽限期";return "已到期"}\nfunction limitHint(s,k){const o=s.quotaOverrides||{},p=s.planLimits||{};if(!(k in o))return "";return ` · 套餐 ${planLimit(p[k])} → 人工 ${planLimit(o[k])}`}\nfunction renderSchools(){const q=$("#search").value.trim().toLowerCase(),f=$("#statusFilter").value,pf=$("#planFilter").value;const rows=schools.filter(s=>{if(pf&&s.planCode!==pf)return false;if(f==="followup"&&!s.followupDue)return false;if(f&&f!=="followup"&&s.operatorStatus!==f)return false;const text=[s.schoolName,s.schoolCode,s.contactName,s.contactValue,s.planName,...(s.admins||[]).flatMap(x=>[x.name,x.username])].join(" ").toLowerCase();return !q||text.includes(q)});$("#schools").innerHTML=rows.length?rows.map(s=>`<div class="card school"><div class="school-head"><div><h3>${esc(s.schoolName)} <span class="badge">${esc(s.schoolCode||"")}</span></h3><div class="muted">${esc(s.contactName||"未填写联系人")}${s.contactValue?` · ${esc(s.contactValue)}`:""} · 学校ID ${s.schoolID}${(!s.contactName&&!s.contactValue)?` <span class="badge amber">联系资料待完善</span>`:""}</div></div><div><span class="badge ${statusClass(s.operatorStatus)}">${esc(s.operatorStatusName)}</span> <span class="badge">${esc(s.planName)}</span>${s.hasQuotaOverride?` <span class="badge amber">人工额度</span>`:""}</div></div><div class="usage"><div><b>${s.usage?.teachers??0} / ${planLimit(s.limits?.teachers)}</b><small>教师${esc(limitHint(s,"teachers"))}</small></div><div><b>${s.usage?.classes??0} / ${planLimit(s.limits?.classes)}</b><small>班级${esc(limitHint(s,"classes"))}</small></div><div><b>${s.usage?.students??0} / ${planLimit(s.limits?.students)}</b><small>学生${esc(limitHint(s,"students"))}</small></div></div><div class="muted">${esc(expiryText(s))}${s.admins?.length?` · 管理员 ${esc(s.admins.map(x=>x.username).join("、"))}`:""}</div>${s.customerNote?`<div class="note" style="margin-top:10px">${esc(s.customerNote)}</div>`:""}${s.latestFollowUp?`<div class="note" style="margin-top:10px;${s.followupDue?"background:#ffecef;color:var(--red)":""}"><b>最近跟进：</b>${esc(s.latestFollowUp.content)}${s.nextFollowupDate?`<br><b>下次跟进：</b>${esc(s.nextFollowupDate)}${s.followupDue?"（待处理）":""}`:""}</div>`:""}<div class="quick"><button class="btn" onclick="customPlan(${s.schoolID})">套餐 / 到期日</button><button class="btn" onclick="editQuota(${s.schoolID})">调整额度</button><button class="btn ${s.schoolActive?\'danger\':\'green\'}" onclick="toggleSchool(${s.schoolID},${s.schoolActive?\'false\':\'true\'})">${s.schoolActive?\'暂停学校\':\'恢复学校\'}</button><button class="btn primary" onclick="addFollowUp(${s.schoolID})">记录跟进</button><button class="btn" onclick="showFollowUps(${s.schoolID})">跟进历史</button><button class="btn" onclick="editCustomer(${s.schoolID})">编辑客户资料</button><button class="btn" onclick="copyLoginInfo(${s.schoolID})">复制登录信息</button><button class="btn" onclick="showOperations(${s.schoolID})">操作记录</button><button class="btn" onclick="showEvents(${s.schoolID})">商业历史</button><button class="btn" onclick="resetAdmin(${s.schoolID})">重置管理员密码</button><button class="btn" onclick="quick(${s.schoolID},\'teacher_pro\',\'trial\',14,365,7,\'14天教师专业版试用\')">14天专业版试用</button><button class="btn green" onclick="quick(${s.schoolID},\'school_standard\',\'active\',14,365,7,\'学校标准版年付\')">标准版年付</button></div></div>`).join(""):`<div class="card muted">没有匹配客户</div>`}\nasync function quick(id,plan,status,trial,period,grace,note){if(!confirm(`确认：${note}？`))return;try{await op(`/operator/subscriptions/${id}`,{method:"POST",body:JSON.stringify({plan_code:plan,status,trial_days:trial,period_days:period,grace_days:grace,end_date:"",note})});await reload()}catch(e){toast(e.message)}}\nfunction openModal(html){$("#modal").innerHTML=html;$("#overlay").classList.add("show")} function closeModal(){$("#overlay").classList.remove("show")}\nfunction openCreate(){openModal(`<h2>新建试用客户</h2><div class="formgrid"><label>学校名称<input id="cSchool" placeholder="例如：长缨实验小学"></label><label>学校代码<input id="cCode" placeholder="例如：CY001"></label><label>管理员姓名<input id="cAdminName" value="管理员"></label><label>管理员账号<input id="cAdminUser" placeholder="例如：admin_cy001"></label><label>临时密码<input id="cPassword" placeholder="至少8位，含字母和数字"></label><label>联系人<input id="cContactName" placeholder="老师/校长姓名"></label><label class="wide">联系方式<input id="cContactValue" placeholder="手机号、微信工作号或邮箱"></label><label>初始套餐<select id="cPlan">${plans.map(p=>`<option value="${p.code}" ${p.code==="teacher_pro"?"selected":""}>${esc(p.name)}</option>`).join("")}</select></label><label>状态<select id="cStatus"><option value="trial">14天试用</option><option value="active">直接开通年付</option></select></label><label class="wide">备注<textarea id="cNote" placeholder="客户来源、沟通情况等"></textarea></label></div><div class="actions" style="margin-top:14px"><button class="btn primary" onclick="createSchool()">创建客户</button><button class="btn" onclick="closeModal()">取消</button></div>`)}\nasync function createSchool(){const body={school_name:$("#cSchool").value.trim(),school_code:$("#cCode").value.trim(),admin_name:$("#cAdminName").value.trim(),admin_username:$("#cAdminUser").value.trim(),admin_password:$("#cPassword").value,contact_name:$("#cContactName").value.trim(),contact_value:$("#cContactValue").value.trim(),source:"operator_console",plan_code:$("#cPlan").value,status:$("#cStatus").value,trial_days:14,period_days:365,grace_days:7,note:$("#cNote").value.trim()};try{const d=await op("/operator/schools/create",{method:"POST",body:JSON.stringify(body)});const c=d.temporaryCredential;CREATED_CREDENTIAL=`学校：${c.schoolName}\\n学校代码：${c.schoolCode}\\n账号：${c.username}\\n临时密码：${c.password}`;openModal(`<h2>客户创建成功</h2><p class="note">下面是一次性临时登录信息。请安全发送给客户，首次登录会要求修改密码。</p><div class="secret">学校：${esc(c.schoolName)}<br>学校代码：${esc(c.schoolCode)}<br>账号：${esc(c.username)}<br>临时密码：${esc(c.password)}</div><div class="actions" style="margin-top:12px"><button class="btn primary" onclick="copyCredential()">复制登录信息</button><button class="btn" onclick="closeModal();reload()">完成</button></div>`)}catch(e){toast(e.message)}}\nasync function copyCredential(){try{await navigator.clipboard.writeText(CREATED_CREDENTIAL);toast("已复制")}catch{toast("复制失败，请手动选择")}}\nfunction addFollowUp(id){const s=schools.find(x=>x.schoolID===id),tomorrow=new Date(Date.now()+86400000*3).toISOString().slice(0,10);openModal(`<h2>${esc(s.schoolName)} · 记录商业跟进</h2><div class="formgrid"><label>跟进类型<select id="fType"><option value="contact">联系沟通</option><option value="demo">产品演示</option><option value="quote">报价</option><option value="payment">付款/续费</option><option value="other">其他</option></select></label><label>下次跟进日期（可选）<input id="fNext" type="date" value="${tomorrow}"></label><label class="wide">本次跟进内容<textarea id="fContent" placeholder="例如：已演示成长档案与成长报告，客户希望下周确认试用名单。"></textarea></label></div><div class="actions" style="margin-top:14px"><button class="btn primary" onclick="saveFollowUp(${id})">保存跟进</button><button class="btn" onclick="closeModal()">取消</button></div>`)}\nasync function saveFollowUp(id){try{await op(`/operator/schools/${id}/followups`,{method:"POST",body:JSON.stringify({follow_type:$("#fType").value,content:$("#fContent").value.trim(),next_followup_date:$("#fNext").value})});closeModal();await reload();toast("跟进记录已保存")}catch(e){toast(e.message)}}\nasync function showFollowUps(id){const s=schools.find(x=>x.schoolID===id);try{const rows=await op(`/operator/schools/${id}/followups`);openModal(`<h2>${esc(s?.schoolName||"客户")} · 跟进历史</h2>${rows.length?rows.map(x=>`<div class="event"><b>${esc(x.typeName)}</b><div class="muted">${esc(x.createdAt||"")}${x.nextFollowupDate?` · 下次 ${esc(x.nextFollowupDate)}`:""}</div><div style="margin-top:5px">${esc(x.content)}</div></div>`).join(""):`<p class="muted">暂无跟进记录</p>`}<div class="actions"><button class="btn" onclick="closeModal()">关闭</button></div>`)}catch(e){toast(e.message)}}\nfunction editCustomer(id){const s=schools.find(x=>x.schoolID===id);openModal(`<h2>${esc(s.schoolName)} · 编辑客户资料</h2><div class="formgrid"><label>联系人<input id="eContactName" value="${esc(s.contactName||"")}" placeholder="老师/校长姓名"></label><label>联系方式<input id="eContactValue" value="${esc(s.contactValue||"")}" placeholder="手机号、工作微信或邮箱"></label><label class="wide">客户来源<input id="eSource" value="${esc(s.customerSource||"")}" placeholder="例如：教师转介绍、学校拜访、线上咨询"></label><label class="wide">客户备注<textarea id="eNote">${esc(s.customerNote||"")}</textarea></label></div><div class="actions" style="margin-top:14px"><button class="btn primary" onclick="saveCustomer(${id})">保存客户资料</button><button class="btn" onclick="closeModal()">取消</button></div>`)}\nasync function saveCustomer(id){try{await op(`/operator/schools/${id}/customer`,{method:"POST",body:JSON.stringify({contact_name:$("#eContactName").value.trim(),contact_value:$("#eContactValue").value.trim(),source:$("#eSource").value.trim(),note:$("#eNote").value.trim()})});closeModal();await reload();toast("客户资料已保存")}catch(e){toast(e.message)}}\nasync function copyLoginInfo(id){const s=schools.find(x=>x.schoolID===id),admin=s?.admins?.[0]?.username||"";const text=`长缨辅学登录地址：${location.origin}\\n学校：${s?.schoolName||""}\\n管理员账号：${admin}`;try{await navigator.clipboard.writeText(text);toast("登录信息已复制")}catch{toast("复制失败，请手动记录")}}\nfunction customPlan(id){const s=schools.find(x=>x.schoolID===id);const currentEnd=s.status==="trial"?s.trialEndsAt:s.status==="grace"?s.graceEndsAt:s.periodEndsAt;openModal(`<h2>${esc(s.schoolName)} · 套餐与服务期</h2><div class="formgrid"><label>套餐<select id="uPlan">${plans.map(p=>`<option value="${p.code}" ${p.code===s.planCode?"selected":""}>${esc(p.name)}</option>`).join("")}</select></label><label>订阅状态<select id="uStatus"><option value="trial">试用中</option><option value="active">已开通</option><option value="grace">宽限期</option><option value="expired">已到期</option></select></label><label>明确到期日（优先）<input id="uEnd" type="date" value="${dateInput(currentEnd)}"></label><label>试用天数（未填到期日时）<input id="uTrial" type="number" value="14"></label><label>开通天数（未填到期日时）<input id="uPeriod" type="number" value="365"></label><label>宽限天数<input id="uGrace" type="number" value="7"></label><label class="wide">备注<textarea id="uNote">${esc(s.note||"")}</textarea></label></div><p class="note">填写“明确到期日”后，以该日期当天 23:59 为服务截止；不填则按天数计算。</p><div class="actions"><button class="btn primary" onclick="saveCustom(${id})">保存套餐与服务期</button><button class="btn" onclick="closeModal()">取消</button></div>`);$("#uStatus").value=s.status}\nasync function saveCustom(id){try{await op(`/operator/subscriptions/${id}`,{method:"POST",body:JSON.stringify({plan_code:$("#uPlan").value,status:$("#uStatus").value,trial_days:+$("#uTrial").value||14,period_days:+$("#uPeriod").value||365,grace_days:+$("#uGrace").value||7,end_date:$("#uEnd").value,note:$("#uNote").value.trim()})});closeModal();await reload();toast("套餐与服务期已保存")}catch(e){toast(e.message)}}\nfunction quotaMode(s,k){const o=s.quotaOverrides||{};if(!(k in o))return "inherit";return o[k]===null?"unlimited":"custom"} function quotaNumber(s,k){const o=s.quotaOverrides||{};return (k in o&&o[k]!==null)?o[k]:""}\nfunction quotaRow(label,prefix,resource,s){return `<div class="quota-grid"><b>${label}</b><label>模式<select id="q${prefix}Mode"><option value="inherit">跟随套餐</option><option value="custom">自定义</option><option value="unlimited">不限</option></select></label><label>自定义额度<input id="q${prefix}Num" type="number" min="1" value="${quotaNumber(s,resource)}" placeholder="正整数"></label></div>`}\nfunction editQuota(id){const s=schools.find(x=>x.schoolID===id);openModal(`<h2>${esc(s.schoolName)} · 调整额度</h2><p class="muted">当前套餐：${esc(s.planName)}。单独调整后会覆盖套餐默认额度。</p>${quotaRow("教师","T","teachers",s)}${quotaRow("班级","C","classes",s)}${quotaRow("学生","S","students",s)}<label style="margin-top:12px">备注<textarea id="qNote" placeholder="例如：签约赠送 10 个教师名额"></textarea></label><div class="actions" style="margin-top:14px"><button class="btn primary" onclick="saveQuota(${id})">保存额度</button><button class="btn" onclick="closeModal()">取消</button></div>`);[["T","teachers"],["C","classes"],["S","students"]].forEach(([p,k])=>{$(`#q${p}Mode`).value=quotaMode(s,k)})}\nfunction quotaValue(p){const m=$(`#q${p}Mode`).value;if(m!=="custom")return m;const n=$(`#q${p}Num`).value.trim();return n||"inherit"}\nasync function saveQuota(id){try{await op(`/operator/schools/${id}/quota`,{method:"POST",body:JSON.stringify({teachers:quotaValue("T"),classes:quotaValue("C"),students:quotaValue("S"),note:$("#qNote").value.trim()})});closeModal();await reload();toast("额度已保存")}catch(e){toast(e.message)}}\nasync function toggleSchool(id,active){const s=schools.find(x=>x.schoolID===id),verb=active?"恢复":"暂停";if(!confirm(`确认${verb}“${s.schoolName}”？${active?"恢复后用户可重新登录。":"暂停后学校全部账号将立即无法继续使用，但数据不会删除。"}`))return;const note=prompt(`${verb}原因/备注（可留空）`,"")||"";try{await op(`/operator/schools/${id}/state`,{method:"POST",body:JSON.stringify({active,note})});await reload();toast(`学校已${verb}`)}catch(e){toast(e.message)}}\nfunction compactJson(v){return esc(JSON.stringify(v||{},null,2))}\nasync function showOperations(id=null){try{const rows=await op(`/operator/operations?limit=200${id?`&school_id=${id}`:""}`),s=id?schools.find(x=>x.schoolID===id):null;openModal(`<h2>${esc(s?.schoolName||"全部客户")} · 运营操作记录</h2>${rows.length?rows.map(x=>`<div class="event"><b>${esc(x.actionName)}</b> <span class="badge">${esc(x.schoolName)}</span><div class="muted">${esc(x.createdAt||"")} · ${esc(x.actor||"")}</div>${x.detail?`<div style="margin-top:5px">${esc(x.detail)}</div>`:""}<details><summary class="muted">查看修改前 / 修改后</summary><div class="json">修改前\\n${compactJson(x.before)}\\n\\n修改后\\n${compactJson(x.after)}</div></details></div>`).join(""):`<p class="muted">暂无运营操作记录</p>`}<div class="actions"><button class="btn" onclick="closeModal()">关闭</button></div>`)}catch(e){toast(e.message)}}\nasync function showEvents(id){const s=schools.find(x=>x.schoolID===id);try{const rows=await op(`/operator/schools/${id}/events`);openModal(`<h2>${esc(s?.schoolName||"客户")} · 商业历史</h2>${rows.length?rows.map(x=>`<div class="event"><b>${esc(x.action)}</b> <span class="badge">${esc(planName(x.planCode))}</span> <span class="badge ${statusClass(x.status)}">${esc(x.status||"")}</span><div class="muted">${esc(x.createdAt||"")}</div><div>${esc(x.detail||"")}</div></div>`).join(""):`<p class="muted">暂无历史</p>`}<div class="actions"><button class="btn" onclick="closeModal()">关闭</button></div>`)}catch(e){toast(e.message)}}\nfunction resetAdmin(id){const s=schools.find(x=>x.schoolID===id),def=s.admins?.[0]?.username||"";openModal(`<h2>${esc(s.schoolName)} · 重置管理员密码</h2><p class="note">重置后管理员首次登录必须修改密码。</p><div class="formgrid"><label>管理员账号<input id="rUser" value="${esc(def)}"></label><label>新临时密码<input id="rPass" placeholder="至少8位，含字母和数字"></label></div><div class="actions" style="margin-top:14px"><button class="btn danger" onclick="doReset(${id})">确认重置</button><button class="btn" onclick="closeModal()">取消</button></div>`)}\nasync function doReset(id){const p=$("#rPass").value;if(!confirm("确认重置管理员密码？"))return;try{const d=await op(`/operator/schools/${id}/reset-admin`,{method:"POST",body:JSON.stringify({username:$("#rUser").value.trim(),new_password:p})});openModal(`<h2>重置成功</h2><div class="secret">账号：${esc(d.username)}<br>临时密码：${esc(p)}</div><p class="note">请安全发送给客户，首次登录会要求修改密码。</p><div class="actions"><button class="btn" onclick="closeModal()">完成</button></div>`)}catch(e){toast(e.message)}}\nif(KEY){$("#key").value=KEY;connect()}\n</script></body></html>\n'

